class TTSError(RasaException):
    pass


class TTSConfigError(RasaException):
    """Error raised when TTS configuration is invalid."""

    pass


class TTSWordTimestamp(BaseModel):
    """Represent a provider-neutral word boundary for one synthesis segment."""

    word: str
    start_seconds: float
    end_seconds: float

    model_config = ConfigDict(frozen=True)

    @field_validator("start_seconds", "end_seconds", mode="before")
    @classmethod
    def _validate_timestamp_value(cls, value: object) -> float:
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(value)
            or value < 0
        ):
            raise ValueError("timestamp must be a non-negative finite number")
        return float(value)

    @model_validator(mode="after")
    def _validate_bounds(self) -> "TTSWordTimestamp":
        if self.end_seconds < self.start_seconds:
            raise ValueError("word end is before its start")
        return self

    @classmethod
    def from_provider_values(
        cls, word: object, start: object, end: object
    ) -> "TTSWordTimestamp":
        """Build one word boundary from a provider row."""
        if not isinstance(word, str):
            raise ValueError("word must be a string")
        return cls.model_validate(
            {"word": word, "start_seconds": start, "end_seconds": end}
        )


class TTSWordTimestamps(BaseModel):
    """Represent word boundaries emitted for one synthesis segment."""

    timestamps: List[TTSWordTimestamp]

    model_config = ConfigDict(frozen=True)

    @classmethod
    def parse(
        cls, words: object, starts: object, ends: object
    ) -> Optional["TTSWordTimestamps"]:
        """Build timestamps when the three lists match and every row is valid.

        ``words``, ``starts``, and ``ends`` are parallel. Each row is one word
        and its start and end in seconds.
        """
        if not (
            isinstance(words, list)
            and isinstance(starts, list)
            and isinstance(ends, list)
            and len(words) == len(starts) == len(ends)
        ):
            return None

        timestamps: List[TTSWordTimestamp] = []
        for word, start, end in zip(words, starts, ends):
            try:
                timestamps.append(
                    TTSWordTimestamp.from_provider_values(word, start, end)
                )
            except ValueError:
                return None
        return cls(timestamps=timestamps)

    def shifted(self, offset_seconds: float) -> "TTSWordTimestamps":
        """Return timestamps moved onto the response clock.

        Providers that synthesize a response in several runs measure each run's
        timestamps from the start of that run's audio. Adding the audio already
        received puts every run on one clock counted from the response start.
        """
        if offset_seconds == 0:
            return self
        return TTSWordTimestamps(
            timestamps=[
                timestamp.model_copy(
                    update={
                        "start_seconds": timestamp.start_seconds + offset_seconds,
                        "end_seconds": timestamp.end_seconds + offset_seconds,
                    }
                )
                for timestamp in self.timestamps
            ]
        )


TTSStreamEvent = Union[RasaAudioBytes, TTSWordTimestamps]


T = TypeVar("T", bound="TTSEngineConfig")
E = TypeVar("E", bound="TTSEngine")
L = TypeVar("L", bound="TTSLanguageMapEntry")


class TTSLanguageMapEntry(BaseModel):
    """Entry in the language_map mapping Rasa language to TTS settings.

    Usually a TTS Engine will require at least a language code and voice
    identifier to be able to synthesize speech. This class can be extended with
    additional fields as needed for specific engines.

    Attributes:
        language: Optional TTS-specific language code (e.g., 'en-US' for Azure).
        voice: Optional TTS-specific voice identifier.
        model: Optional model identifier for engines that support multiple models.
    """

    language: Optional[str] = None
    voice: Optional[str] = None
    model: Optional[str] = None


class TTSEngineConfig(BaseModel):
    """Base configuration for TTS engines.

    Attributes:
        timeout: Request timeout in seconds.
        language_map: Maps Rasa language codes to TTS-specific settings.
            Each TTS engine should provide sensible defaults.
        language: Deprecated. Use ``language_map`` instead.
        voice: Deprecated. Use ``language_map`` instead.
        model: Deprecated. Use ``language_map`` instead.
    """

    # Deprecated: set these inside language_map instead
    language: Optional[str] = None
    voice: Optional[str] = None
    model: Optional[str] = None
    timeout: int = 30
    language_map: Optional[Dict[str, TTSLanguageMapEntry]] = None

    model_config = ConfigDict(extra="allow")

    @model_validator(mode="after")
    def _validate_language_fields(self, info: ValidationInfo) -> "TTSEngineConfig":
        """Validate mutual exclusivity of deprecated fields and language_map.

        Skipped during merge(), which intentionally combines a user config
        (potentially with deprecated fields) with a default config (which always
        has language_map). apply_deprecated_fields() folds them together after.
        """
        if info.context and info.context.get("merging"):
            return self

        if self.model_extra:
            unknown = ", ".join(f"'{k}'" for k in self.model_extra)
            raise_warning(
                f"Unknown TTS config field(s) {unknown} will be ignored. "
                "Please check the documentation for valid configuration options."
            )

        has_deprecated = (
            self.language is not None
            or self.voice is not None
            or self.model is not None
        )
        has_language_map = self.language_map is not None

        if has_deprecated and has_language_map:
            raise ValueError(
                "Cannot specify both top-level 'language'/'voice'/'model' and "
                "'language_map'. Remove 'language', 'voice', and 'model' and "
                "configure 'language_map' only."
            )

        if has_deprecated:
            used_fields = sorted(
                f
                for f in ("language", "model", "voice")
                if getattr(self, f) is not None
            )
            field_list = ", ".join(f"'{f}'" for f in used_fields)
            raise_deprecation_warning(
                f"Top-level TTS config field(s) {field_list} are deprecated. "
                "Use 'language_map' instead."
            )

        return self

    def merge(self: T, other: Optional[T]) -> T:
        """Merges two configs while dropping None values of the second config."""
        if other is None:
            return self
        other_dict = other.model_dump()
        other_dict_clean = {k: v for k, v in other_dict.items() if v is not None}
        merged = {**self.model_dump(), **other_dict_clean}
        return self.__class__.model_validate(merged, context={"merging": True})

    def apply_deprecated_fields(self, rasa_language: str) -> "TTSEngineConfig":
        """Fold top-level deprecated fields into language_map[rasa_language].

        Moves ``language``, ``voice``, or ``model`` values set at the top level
        into the language_map entry for ``rasa_language``. The FutureWarning is
        is emitted earlier, during model validation.
        """
        updates = {
            k: v
            for k, v in [
                ("language", self.language),
                ("voice", self.voice),
                ("model", self.model),
            ]
            if v is not None
        }
        if not updates:
            return self

        existing_map = dict(self.language_map or {})
        existing_entry = existing_map.get(rasa_language, TTSLanguageMapEntry())
        existing_map[rasa_language] = existing_entry.model_copy(update=updates)
        return self.model_copy(
            update={
                "language": None,
                "voice": None,
                "model": None,
                "language_map": existing_map,
            }
        )

    def validate_language_map_keys(
        self,
        rasa_language: Optional[str],
        additional_languages: Optional[List[str]] = None,
    ) -> None:
        """Validate that language_map is configured and contains valid languages.

        Checks that:
        1. language_map is not empty
        2. rasa_language is provided
        3. rasa_language exists in language_map
        4. All language_map keys are in the set of allowed languages
           (rasa_language + additional_languages)
        """
        if not self.language_map:
            raise TTSConfigError(
                "TTS configuration requires 'language_map' to be set. "
                "The language_map should map Rasa language codes to TTS settings."
            )

        if rasa_language is None:
            raise TTSConfigError(
                "A language key must be provided in config.yml, "
                "this key is used to determine which language and "
                "voice to use from the language_map."
            )

        if rasa_language not in self.language_map:
            available_languages = list(self.language_map.keys())
            raise TTSConfigError(
                f"Language '{rasa_language}' not found in language_map. "
                f"Available languages: {available_languages}. "
                f"Please add '{rasa_language}' to the language_map configuration."
            )

        # Validate that language_map keys are subset of allowed languages
        allowed_languages = {rasa_language}
        if additional_languages:
            allowed_languages.update(additional_languages)

        language_map_keys = set(self.language_map.keys())
        invalid_keys = language_map_keys - allowed_languages
        if invalid_keys:
            raise TTSConfigError(
                f"language_map contains invalid language keys: {sorted(invalid_keys)}. "
                f"Allowed languages are: {sorted(allowed_languages)}. "
                "These must match 'language' and 'additional_languages' in config.yml."
            )

        missing_keys = allowed_languages - language_map_keys
        if missing_keys:
            logger.warning(
                "tts_engine_config.missing_language_map_keys",
                message="language_map is "
                f"missing key(s): {', '.join(sorted(missing_keys))}. "
                "These must match 'language' and 'additional_languages' in config.yml.",
            )


class StreamState(enum.Enum):
    NO_STREAMING = "no_streaming"
    SENDING_RESPONSE_CHUNKS = "sending_response_chunks"
    RESPONSE_CHUNKS_SENT = "response_chunks_sent"
    INTERRUPTED = "interrupted"


class _TTSResponseState(enum.Enum):
    OPEN = "open"
    FINISHING = "finishing"
    INTERRUPTING = "interrupting"
    FINISHED = "finished"
    INTERRUPTED = "interrupted"


_AUDIO_STREAM_END = object()


class TTSResponse:
    """Represent one streaming response produced by a TTS engine.

    The engine owns the provider reader for the lifetime of the response. Cancelling
    a consumer therefore does not cancel or abandon the provider stream.
    """

    def __init__(self, engine: "TTSEngine", response_id: str) -> None:
        self._engine = engine
        self._response_id = response_id
        self._state = _TTSResponseState.OPEN
        self._audio_queue: asyncio.Queue[object] = asyncio.Queue()
        self._word_timestamps_queue: asyncio.Queue[TTSWordTimestamps] = asyncio.Queue()
        self._finished = asyncio.Event()
        self._reader_task: Optional[asyncio.Task[None]] = None
        self._interrupt_task: Optional[asyncio.Task[None]] = None
        self._error: Optional[Exception] = None
        self._audio_consumer_active = False

    @property
    def response_id(self) -> str:
        """Return the response identifier."""
        return self._response_id

    async def write(self, text: str) -> None:
        """Queue a text fragment for synthesis."""
        if self._state is not _TTSResponseState.OPEN:
            if self._error is not None:
                raise self._error
            raise TTSError("TTS response no longer accepts text")
        await self._engine.send_text_chunk(text)

    async def finish(self) -> None:
        """Signal that all text has been written without waiting for playback."""
        if self._state is _TTSResponseState.OPEN:
            self._state = _TTSResponseState.FINISHING
            await self._engine.signal_text_done()

    def interrupt(self) -> Awaitable[None]:
        """Stop synthesis and return when stale provider output is reconciled.

        Interruption begins synchronously: audio delivery is disabled and an
        engine-owned cleanup task is created before this method returns. The cleanup
        consequently survives cancellation of the caller awaiting the result.
        """
        if self._finished.is_set():
            return asyncio.create_task(self.wait_until_finished())

        if self._interrupt_task is None:
            self._state = _TTSResponseState.INTERRUPTING
            self._discard_queued_audio()
            self._interrupt_task = asyncio.create_task(self._run_interrupt())
        return asyncio.shield(self._interrupt_task)

    async def wait_until_finished(self) -> None:
        """Wait until the provider stream reaches a response boundary."""
        await self._finished.wait()
        if self._error is not None:
            raise self._error

    def __aiter__(self) -> AsyncIterator[RasaAudioBytes]:
        """Iterate over audio that is still eligible for delivery."""
        return self._iterate_audio()

    def drain_word_timestamps(self) -> List[TTSWordTimestamps]:
        """Return all timestamp batches received without blocking."""
        batches: List[TTSWordTimestamps] = []
        while True:
            try:
                batches.append(self._word_timestamps_queue.get_nowait())
            except asyncio.QueueEmpty:
                return batches

    def _start_reader(self) -> None:
        self._reader_task = asyncio.create_task(self._engine._read_response_audio(self))

    async def _run_interrupt(self) -> None:
        try:
            await self._engine.signal_interrupt()
            await asyncio.wait_for(
                asyncio.shield(self.wait_until_finished()),
                timeout=float(self._engine.config.timeout),
            )
        except asyncio.TimeoutError as error:
            await self._engine._recover_interrupted_response(self)
            raise TTSError("Timed out waiting for TTS interruption") from error
        except asyncio.CancelledError:
            raise
        except Exception:
            await self._engine._recover_interrupted_response(self)
            raise

    async def _iterate_audio(self) -> AsyncIterator[RasaAudioBytes]:
        if self._audio_consumer_active:
            raise TTSError("TTS response already has an audio consumer")
        self._audio_consumer_active = True
        try:
            while True:
                item = await self._audio_queue.get()
                if item is _AUDIO_STREAM_END:
                    return
                if isinstance(item, Exception):
                    raise item
                if not isinstance(item, RasaAudioBytes):
                    raise TTSError("TTS engine returned an invalid audio item")
                yield item
        finally:
            self._audio_consumer_active = False

    def _accept_audio(self, audio: RasaAudioBytes) -> None:
        if self._state is not _TTSResponseState.INTERRUPTING:
            self._audio_queue.put_nowait(audio)

    def _accept_word_timestamps(self, timestamp_batch: TTSWordTimestamps) -> None:
        if self._state is not _TTSResponseState.INTERRUPTING:
            self._word_timestamps_queue.put_nowait(timestamp_batch)

    def _complete(self, error: Optional[Exception] = None) -> None:
        if self._finished.is_set():
            return
        self._error = error
        if error is not None:
            self._audio_queue.put_nowait(error)
        self._audio_queue.put_nowait(_AUDIO_STREAM_END)
        self._state = (
            _TTSResponseState.INTERRUPTED
            if self._state is _TTSResponseState.INTERRUPTING
            else _TTSResponseState.FINISHED
        )
        self._finished.set()
        self._engine._response_finished(self)

    def _discard_queued_audio(self) -> None:
        while not self._audio_queue.empty():
            self._audio_queue.get_nowait()
        while not self._word_timestamps_queue.empty():
            self._word_timestamps_queue.get_nowait()


class TTSEngine(Generic[T]):
    required_env_vars: Tuple[str, ...] = ()
    required_packages: Tuple[str, ...] = ()
    stream_state: StreamState = StreamState.NO_STREAMING
    # If TTS supports input text streaming
    streaming_input: bool = False

    # Runtime language/model state
    current_language_config: CurrentLanguageConfig

    @classmethod
    def name(cls) -> str:
        raise NotImplementedError(
            "Subclasses must implement name() method to return engine name."
        )

    def __init__(
        self,
        rasa_language: str,
        format: AudioFormat,
        config: Optional[T] = None,
        additional_languages: Optional[List[str]] = None,
    ):
        self.audio_format = format
        self.config = self.get_default_config(rasa_language).merge(config)
        self.config = cast(T, self.config.apply_deprecated_fields(rasa_language))
        self.config.validate_language_map_keys(rasa_language, additional_languages)
        validate_environment(
            self.required_env_vars,
            self.required_packages,
            f"TTS Engine {self.__class__.__name__}",
        )
        self._set_current_language_config(rasa_language)
        self.stop_streaming_output_audio_chunks = False
        # Serializes engine writes (send_text_chunk / signal_text_done /
        # signal_interrupt) against the close+reopen in ``set_language``.
        # Lazy so it binds to the running event loop on first use.
        self._engine_lock: Optional[asyncio.Lock] = None
        self._initialize_response_runtime()

    def _initialize_response_runtime(self) -> None:
        self._response_lock: Optional[asyncio.Lock] = None
        self._active_response: Optional[TTSResponse] = None

    def _active_response_id(self) -> str:
        if self._active_response is None:
            raise TTSError("No active TTS response")
        return self._active_response.response_id

    def interrupt(self) -> Awaitable[None]:
        """Interrupt the active response and reconcile its provider stream."""
        self.stop_streaming_output_audio_chunks = True
        self.stream_state = StreamState.INTERRUPTED
        if self._active_response is not None:
            return self._active_response.interrupt()

        completed: asyncio.Future[None] = asyncio.get_running_loop().create_future()
        completed.set_result(None)
        return completed

    def _get_engine_lock(self) -> asyncio.Lock:
        if self._engine_lock is None:
            self._engine_lock = asyncio.Lock()
        return self._engine_lock

    async def _reconnect_with_lock(self) -> None:
        async with self._get_engine_lock():
            await self.close_connection()
            await self.connect()

    async def prepare_response(
        self, streaming_config: Optional[StreamingConfig] = None
    ) -> None:
        """Called before a streaming response begins.

        Engines can override to adjust per-response behavior
        (e.g., switching between streaming and non-streaming modes).
        """
        pass

    async def start_response(
        self, streaming_config: Optional[StreamingConfig] = None
    ) -> TTSResponse:
        """Start a response using the engine's streaming provider primitives.

        Subclasses only need to implement ``send_text_chunk``,
        ``signal_text_done``, ``signal_interrupt``, and ``stream_audio``. The base
        class owns reader lifetime, interruption draining, and response isolation.
        """
        if self._response_lock is None:
            self._response_lock = asyncio.Lock()

        async with self._response_lock:
            if self._active_response is not None:
                await self._active_response.interrupt()

            await self.prepare_response(streaming_config)
            response = TTSResponse(self, uuid4().hex)
            self._active_response = response
            response._start_reader()
            return response

    async def _read_response_audio(self, response: TTSResponse) -> None:
        error: Optional[Exception] = None
        try:
            async for event in self.stream_audio_events():
                if isinstance(event, TTSWordTimestamps):
                    response._accept_word_timestamps(event)
                else:
                    response._accept_audio(event)
        except asyncio.CancelledError:
            raise
        except Exception as caught_error:
            error = caught_error
        finally:
            response._complete(error)

    async def _recover_interrupted_response(self, response: TTSResponse) -> None:
        try:
            await self.close_connection()
        finally:
            if response._reader_task is not None and not response._reader_task.done():
                response._reader_task.cancel()
                await asyncio.gather(response._reader_task, return_exceptions=True)
            response._complete()
        await self.connect()

    def _response_finished(self, response: TTSResponse) -> None:
        if response is self._active_response:
            self._active_response = None

    @voice_tracing.traced_tts_connect
    async def connect(self, config: Optional[T] = None) -> None:
        """Establish connection to the TTS engine if necessary."""
        return

    @voice_tracing.traced_tts_disconnect
    async def close_connection(self) -> None:
        """Cleanup the connection if necessary."""
        return

    async def __aenter__(self) -> "TTSEngine[T]":
        """Connect when entering an ``async with`` block.

        Provided so callers can manage the engine lifecycle with
        ``async with tts_engine_from_config(...) as engine:`` instead of
        pairing ``connect()`` / ``close_connection()`` by hand. The manual
        methods remain available and unchanged, so this is fully
        backward-compatible.
        """
        await self.connect()
        return self

    async def __aexit__(
        self,
        exc_type: Optional[Type[BaseException]],
        exc_val: Optional[BaseException],
        exc_tb: Optional[TracebackType],
    ) -> bool:
        """Close the connection when leaving the block, even on exceptions.

        Returns ``False`` so any exception raised inside the block continues
        to propagate after cleanup.
        """
        await self.close_connection()
        return False

    async def send_text_chunk(self, text: str) -> None:
        """Send text chunks to the TTS system.

        This method sends text to the TTS engine but does not return audio.
        Audio should be retrieved via stream_audio().

        Subclasses should implement this to send text to their specific engine.
        """
        pass

    async def signal_text_done(self) -> None:
        """Signal TTS engine to process any remaining buffered text.

        This tells the TTS engine that all text has been sent and to finish
        processing and prepare to end the stream.

        Returns:
            bool: Whether the engine supports streaming responses.
        """
        pass

    async def stream_audio(self) -> AsyncIterator[RasaAudioBytes]:
        """Stream audio output from the TTS engine.

        This continuously yields audio chunks as they are produced by the engine.
        Used in conjunction with send_text_chunk() for streaming responses.
        """
        yield RasaAudioBytes(b"", format=self.audio_format)

    async def stream_audio_events(self) -> AsyncIterator[TTSStreamEvent]:
        """Stream audio and optional provider timing events.

        The default preserves compatibility with audio-only engines.
        """
        async for audio in self.stream_audio():
            yield audio

    async def synthesize(
        self, text: str, config: Optional[T] = None
    ) -> AsyncIterator[RasaAudioBytes]:
        """Generate speech from text using a remote TTS system."""
        yield RasaAudioBytes(b"", format=self.audio_format)

    def engine_bytes_to_rasa_audio_bytes(self, chunk: bytes) -> RasaAudioBytes:
        """Convert the generated TTS audio bytes into rasa audio bytes."""
        raise NotImplementedError

    async def signal_interrupt(self) -> None:
        """Cancel the TTS engine buffer."""
        pass

    @staticmethod
    def get_default_config(rasa_language: str) -> T:
        """Get the default config for this component."""
        raise NotImplementedError

    @classmethod
    def from_config_dict(
        cls: Type[E],
        config: Dict,
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> E:
        raise NotImplementedError

    async def set_language(self, rasa_language: str) -> bool:
        """Update the TTS language for subsequent synthesis calls.

        Called by the voice channel when the language slot changes.

        Args:
            rasa_language: Value of Rasa's language slot.

        Returns:
            True if the language actually changed (so the subclass should
            recycle its connection), False if this was a no-op.
        """
        if self.current_language_config.is_same_language(rasa_language):
            return False

        old_language_config = self.current_language_config
        self._set_current_language_config(rasa_language)
        logger.info(
            f"tts.{self.name()}.language_changed",
            before=old_language_config,
            after=self.current_language_config,
        )
        return True

    def _set_current_language_config(self, rasa_language: str) -> None:
        """Helper method to set the current language configuration."""
        assert (
            self.config.language_map is not None
        ), "language_map must be set in config"
        try:
            entry = self.config.language_map[rasa_language]
        except KeyError:
            logger.error(
                f"tts.{self.name()}.language_not_in_map",
                language=rasa_language,
                available_languages=list(self.config.language_map.keys()),
            )
            return
        self.current_language_config = CurrentLanguageConfig(
            rasa_language_key=rasa_language,
            engine_language_key=entry.language,
            voice=entry.voice,
            model=entry.model,
        )
